<script>
function showToast(message){const toast=document.getElementById('toast');toast.textContent=message;toast.classList.add('show');window.setTimeout(()=>toast.classList.remove('show'),4000);}
window.addEventListener('DOMContentLoaded',()=>{const params=new URLSearchParams(location.search);if(params.has('error'))showToast('Please check your details and try again.');else if(params.has('msg'))showToast(params.get('msg'));});
</script>
